'use strict';
function render(){syncModeBanner();syncTestDateControl();document.getElementById('nav').innerHTML=TABS.map(([id,ico,name])=>`<button class="${tab===id?'active':''}" data-tab="${id}"><span class="ico">${ico}</span>${name}</button>`).join('');document.getElementById('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.getElementById('fab').style.display=['home','settings','housing'].includes(tab)?'none':'block';let v=document.getElementById('view');v.innerHTML=tab==='home'?home():tab==='tracking'?trackingView():tab==='expenses'?expenseView():tab==='rules'?rulesView():tab==='income'?incomeView():tab==='housing'?housingView():settingsView();bindView()}
function housingState(){
 if(!data.logement||typeof data.logement!=='object')data.logement={habite:'julien',mode:'prorata',julien:{depenses:[],recettes:[]},carla:{depenses:[],recettes:[]}};
 for(const who of ['julien','carla']){if(!data.logement[who])data.logement[who]={depenses:[],recettes:[]};for(const key of ['depenses','recettes'])if(!Array.isArray(data.logement[who][key]))data.logement[who][key]=[]}
 if(!['julien','carla'].includes(data.logement.habite))data.logement.habite='julien';if(!['prorata','egal'].includes(data.logement.mode))data.logement.mode='prorata';return data.logement
}
function sameId(a,b){return String(a)===String(b)}
function housingCalc(who,k=monthKey){let h=housingState()[who],expenses=(h.depenses||[]).map(id=>data.expenses.find(e=>sameId(e.id,id))).filter(e=>e&&!isHousingAdjustment(e)),incomes=(h.recettes||[]).map(id=>(data.incomes||[]).find(i=>sameId(i.id,id))).filter(i=>i&&!i.autoHousingAdjustment&&i.name!=='Ajustement frais logement'&&activeIncomeInMonth(i,k)),spent=expenses.reduce((n,e)=>n+(Number(e.amount)||0),0),received=incomes.reduce((n,i)=>n+(Number(i.amount)||0),0);return {expenses,incomes,spent,received,net:spent-received}}
function housingSplit(k=monthKey){let julien=housingCalc('julien',k),carla=housingCalc('carla',k),totalNet=julien.net+carla.net,share=totalNet/2,owed=share-carla.net;return {julien,carla,totalNet,share,owner:'J',guest:'C',owed}}
function housingDetails(items,type){return items.length?`<div class="housing-items">${items.map(x=>`<div class="housing-item"><span>${esc(x.name)}</span><b>${eur(x.amount)}</b></div>`).join('')}</div>`:`<div class="housing-empty">Aucune ${type} liée à ce bien pour ${esc(monthName(monthKey))}.</div>`}
function housingPropertyCard(who){let isJ=who==='julien',title=isJ?'Bien de Julien':'Bien de Carla',cls=isJ?'julien':'carla',calc=housingCalc(who);return `<article class="housing-property ${cls}"><div class="housing-property-head"><div><div class="housing-kicker">${isJ?'BIEN 01':'BIEN 02'}</div><h2>${title}</h2></div><span class="housing-owner-tag">${isJ?'Julien':'Carla'}</span></div><div class="housing-net-label">Coût net · ${esc(monthName(monthKey))}</div><div class="housing-net">${eur(calc.net)}</div><div class="housing-equation"><span>Dépenses ${eur(calc.spent)}</span><span>−</span><span>Recettes ${eur(calc.received)}</span></div><div class="housing-detail-group"><h3>Dépenses incluses</h3>${housingDetails(calc.expenses,'dépense')}</div><div class="housing-detail-group"><h3>Recettes incluses</h3>${housingDetails(calc.incomes,'recette')}</div><button class="btn secondary housing-edit" type="button" data-housing-edit="${who}">Modifier la sélection</button></article>`}
function housingView(){let calc=housingSplit(),owedLabel=calc.owed>=0?'Carla doit à Julien':'Julien doit à Carla';return `<div class="eyebrow">Biens immobiliers du couple</div><h1 class="hero">Le <em>logement.</em></h1><div class="housing-summary"><div class="housing-summary-top"><span>Coût net total des deux biens</span><span class="housing-live-tag">Partage 50 / 50</span></div><strong>${eur(calc.totalNet)}</strong><div class="housing-summary-foot">Chaque bien conserve son coût net. Le total est réparti à parts égales entre Julien et Carla.</div><div class="housing-shares"><div class="housing-share j"><span>Part due par Julien</span><b>${eur(calc.share)}</b></div><div class="housing-share c"><span>Part due par Carla</span><b>${eur(calc.share)}</b></div></div><div class="housing-due"><span>${owedLabel}</span><b>${eur(Math.abs(calc.owed))}</b></div></div><p class="housing-explain">Ajustement des frais de logement : pour chacun, part due (50 % du coût net cumulé des deux biens) moins coût net porté par son bien. Le solde indique qui rembourse l’autre.</p><div class="housing-properties">${housingPropertyCard('julien')}${housingPropertyCard('carla')}</div><article class="card housing-other-note"><b>Coûts nets conservés par bien</b><span>Julien : ${eur(calc.julien.net)} · Carla : ${eur(calc.carla.net)}. Ces deux coûts sont additionnés avant le partage égalitaire.</span></article>`}
function housingSelectionModal(who){
 housingExpenseFilter='Logement';
 let key=who==='julien'?'julien':'carla',title=who==='julien'?'Bien de Julien':'Bien de Carla',h=housingState()[key],expenses=data.expenses.filter(e=>!isHousingAdjustment(e)).sort((a,b)=>String(a.name).localeCompare(String(b.name),'fr')),incomes=(data.incomes||[]).filter(i=>!i.autoHousingAdjustment&&i.name!=='Ajustement frais logement').sort((a,b)=>String(a.name).localeCompare(String(b.name),'fr'));
 let categoryMatches=(x,f=housingExpenseFilter)=>{let c=String(x.category||'').trim().toLocaleLowerCase('fr');return f==='Logement'?c==='logement':['impôts/taxes','impôts','taxes','impôts et taxes','impots et taxes'].includes(c)};
 let options=(items,selected,type)=>items.length?items.map(x=>{let active=true,amount=Number(x.amount)||0,owner=type==='expense'?'':` · ${x.person==='C'?'Carla':'Julien'}`,matches=type==='income'||categoryMatches(x),checked=selected.some(id=>sameId(id,x.id));return `<label class="housing-choice ${active?'':'inactive'} ${matches?'':'filter-hidden'}"><input type="checkbox" data-housing-kind="${type}" value="${esc(x.id)}" ${checked?'checked':''}><span><b>${esc(x.name)}</b><small>${eur(amount)}${owner}${active?'':` · inactif en ${esc(monthName(monthKey))}`}</small></span></label>`}).join(''):`<div class="housing-empty">Aucun élément enregistré.</div>`;
 let root=modal(`Sélection · ${title}`,`<p class="note">Choisissez les éléments récurrents ou ponctuels qui appartiennent à ce bien. Seuls les éléments actifs sur le mois affiché entrent dans le coût net.</p><h3 class="housing-select-title">Dépenses du logement</h3><div class="housing-filter-chips" role="group" aria-label="Filtrer les dépenses">${[['Logement','Logement'],['ImpôtsTaxes','Impôts et Taxes']].map(([id,label])=>`<button type="button" class="chip ${housingExpenseFilter===id?'selected':''}" data-housing-expense-filter="${id}" aria-pressed="${housingExpenseFilter===id}">${label}</button>`).join('')}</div><div class="housing-select-list">${options(expenses,h.depenses,'expense')}</div><h3 class="housing-select-title">Recettes du logement</h3><div class="housing-filter-chips" role="group" aria-label="Filtrer les revenus"><button type="button" class="chip selected" aria-pressed="true">Revenus</button></div><div class="housing-select-list">${options(incomes,h.recettes,'income')}</div><div class="btnrow housing-save-row"><button type="button" class="btn" id="saveHousingSelection">Enregistrer la sélection</button></div>`);
 root.querySelector('.modal').classList.add('housing-modal');
 root.querySelectorAll('[data-housing-expense-filter]').forEach(b=>b.onclick=()=>{
  housingExpenseFilter=b.dataset.housingExpenseFilter;
  root.querySelectorAll('[data-housing-expense-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});
  root.querySelectorAll('[data-housing-kind="expense"]').forEach(input=>{let item=data.expenses.find(e=>sameId(e.id,input.value))||{};input.closest('.housing-choice').classList.toggle('filter-hidden',!categoryMatches(item)&&!input.checked)});
 });
 root.querySelectorAll('[data-housing-kind="expense"]').forEach(input=>input.onchange=()=>{let item=data.expenses.find(e=>sameId(e.id,input.value))||{};input.closest('.housing-choice').classList.toggle('filter-hidden',!categoryMatches(item)&&!input.checked)});
 root.querySelector('#saveHousingSelection').onclick=()=>{
  let selected=(kind,items)=>[...root.querySelectorAll(`[data-housing-kind="${kind}"]:checked`)].map(input=>items.find(item=>sameId(item.id,input.value))?.id).filter(id=>id!==undefined);
  h.depenses=selected('expense',data.expenses);h.recettes=selected('income',data.incomes||[]);save();root.innerHTML='';render();
 };
}
function settlementMarkup(){let s=settlement(),net=s.net,headline=Math.abs(net)<0.005?'À jour':net>0?`Carla doit ${eur(net)} à Julien`:`Julien doit ${eur(-net)} à Carla`,history=s.reimbursements.map((r,i)=>`<div class="payment-item"><span>${esc(r.date||'')} · ${esc(payerName(r.from))} → ${esc(payerName(r.to))}</span><b>${eur(r.amount)}</b><button class="danger" ${r.expenseId?`data-del-reimbursement-expense="${esc(r.expenseId)}"`:`data-del-reimbursement="${i}"`} aria-label="Supprimer le remboursement">×</button></div>`).join('');return `<article class="card wide settlement-card"><div class="sectionhead" style="margin:0 0 8px"><h2>Remboursements</h2><button type="button" data-add-reimbursement>+ Remboursement</button></div>${history||'<div class="sub">Aucun remboursement saisi ce mois-ci.</div>'}</article>`}
function breakdownButton(amount,scope,person,key,extraClass=''){
 return `<button type="button" class="amount-drilldown ${extraClass}" data-breakdown="${scope}|${person}|${key}" aria-label="Voir le détail ${esc(key)} · ${esc(person==='J'?'Julien':person==='C'?'Carla':'Total')} · ${eur(amount)}">${eur(amount)}</button>`
}
function breakdownSignedButton(amount,scope,person,key){const sign=amount<0?'−':amount>0?'+':'';return `<button type="button" class="amount-drilldown" data-breakdown="${scope}|${person}|${key}" aria-label="Voir le détail ${esc(key)} · ${esc(person==='J'?'Julien':'Carla')} · ${sign}${eur(Math.abs(amount))}">${sign}${eur(Math.abs(amount))}</button>`}
function homeMonthlyTotals(k=monthKey){
 const expenses=expenseItemsForMonth(k),base={J:0,C:0};
 for(const e of expenses){const cents=Math.max(0,Math.round((Number(e.amount)||0)*100)),raw=shares(e,k),j=Math.max(0,Math.min(cents,Math.round((Number(raw[0])||0)*100)));base.J+=j;base.C+=cents-j}
 const calc=housingSplit(k),adjustmentC=Math.round((Number(calc.owed)||0)*100),adjustmentJ=-adjustmentC;
 const people={J:{base:base.J,adjustment:adjustmentJ,total:base.J+adjustmentJ},C:{base:base.C,adjustment:adjustmentC,total:base.C+adjustmentC}};
 return {people,expenseTotal:people.J.total+people.C.total,incomes:{J:Math.round(valIncome('J',k)*100),C:Math.round(valIncome('C',k)*100)},incomeTotal:Math.round((valIncome('J',k)+valIncome('C',k))*100),adjustment:{J:adjustmentJ,C:adjustmentC},expenses};
}
function formatDrillLines(lines,target,keepZero=false){
 let normalized=lines.filter(x=>keepZero||Math.abs(Number(x.retained)||0)>.000001).map(x=>({...x,grossCents:Math.round((Number(x.gross)||0)*100),retainedCents:Math.round((Number(x.retained)||0)*100)}));
 let delta=Math.round((Number(target)||0)*100)-normalized.reduce((n,x)=>n+x.retainedCents,0);
 for(let i=normalized.length-1;i>=0&&delta!==0;i--){let change=delta>0?delta:Math.max(delta,-Math.abs(normalized[i].retainedCents));normalized[i].retainedCents+=change;delta-=change}
 return normalized.map(x=>({...x,gross:x.grossCents/100,retained:x.retainedCents/100}));
}
