     const idx=id==='J'?0:1,who=id==='J'?'Julien':'Carla';
     for(const e of list){const sh=shares(e,monthKey),value=Math.round(Math.max(0,Number(sh[idx])||0)*100)/100;if(value>0)lines.push({id:e.id,component:`personal:${id}`,name:e.name||'Dépense',gross:Math.abs(Number(e.amount)||0),retained:value,party:`${who} · Personnel`,status:isPaid(e,monthKey)?'Payé':'À payer',category:String(e.category||'').trim()})}
