     for(const e of list){const amount=Number(e.amount)||0;if(amount<=0||e.debtRepayment)continue;const state=isPaid(e,monthKey)?'paid':'unpaid';for(const id of ['J','C']){const payer=e.payer==='C'?'C':e.payer==='J'?'J':null,partnerOwner=id==='J'?'Carla':'Julien';let value=0;if(e.owner==='Commun'&&e.settlementMode==='avance'&&e.shareMode==='prorata'&&payer===id&&e.shareJulien!==null&&e.shareJulien!==undefined&&Number.isFinite(Number(e.shareJulien))){const pct=Number(e.shareJulien),partnerPct=id==='J'?100-pct:pct;value=Math.round(amount*partnerPct*100)/10000}else if(e.owner===partnerOwner&&payer===id)value=Math.round(amount*100)/100;if(value>0)lines.push({id:e.id,component:`partner:${id}:${state}`,name:e.name||'Dépense',gross:amount,retained:value,party:`${payerName(payer)} · ${partnerOwner} · Pour partenaire`,status:state==='paid'?'Payé':'À payer',category:String(e.category||'').trim()})}}
